<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { QButton } from '@qingtoolbox/module-ui'
import Palette from './Palette.vue'
import { defaults } from './model'
import { call, getState, settings, type State } from './bridge'
import { compile } from './math'
const state=ref<State>(),s=ref({...defaults}),error=ref(''),busy=ref(false),saved=ref(false)
async function load(){try{state.value=await getState();s.value={...state.value.settings}}catch(e){error.value=String(e)}}
async function save(){busy.value=true;saved.value=false;error.value='';try{compile(s.value.expression);s.value.theme=document.documentElement.dataset.theme??'system';s.value.appearancePreset=document.documentElement.dataset.appearancePreset??'qing-default';state.value=await settings(s.value);saved.value=true;return true}catch(e){error.value=String(e);return false}finally{busy.value=false}}
async function open(){if(!await save())return;try{state.value=await call<State>('showBoard')}catch(e){error.value=String(e)}}
onMounted(load)
</script>
<template><main class="board-settings"><header class="page-header"><div class="page-icon">✎</div><div><p class="eyebrow">QING SCREEN BOARD</p><h1>屏幕画板</h1><p class="muted">把桌面变成画布，灵感不必离开当前画面。</p></div><QButton variant="primary" :loading="busy" @click="open">打开画板</QButton></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><div class="settings-grid"><section class="settings-card"><div class="card-heading"><span class="step">01</span><div><h2>画笔与颜色</h2><p>预设色、调色盘，或输入精确的 RGB 数值。</p></div></div><Palette :color="s.color" @change="s.color=$event;saved=false"/><div class="form-row"><label for="brush-width">画笔宽度</label><input id="brush-width" v-model.number="s.width" type="range" min="1" max="40"/><output>{{s.width}} px</output></div><div class="form-row"><label for="font-size">文字字号</label><input id="font-size" v-model.number="s.fontSize" type="number" min="10" max="160"/><span>px</span></div><label class="field-label" for="default-text">插入文字的初始内容（可留空）</label><textarea id="default-text" v-model="s.text" maxlength="2000" rows="3" placeholder="也可以在画板上点击后直接输入文字"/></section><section class="settings-card"><div class="card-heading"><span class="step">02</span><div><h2>数学函数图像</h2><p>精确计算表达式，选择“函数”后点击屏幕放置。</p></div></div><label class="expression-field"><span>y =</span><input v-model="s.expression" aria-label="函数表达式" maxlength="256" placeholder="sin(x)"/></label><div class="function-presets"><button v-for="f in ['sin(x)','x^2','1/x','sqrt(x)','cos(x)']" :key="f" @click="s.expression=f">{{f}}</button></div><div class="range-grid"><label>X 最小值<input v-model.number="s.xMin" type="number" step="any"/></label><label>X 最大值<input v-model.number="s.xMax" type="number" step="any"/></label><label>Y 最小值<input v-model.number="s.yMin" type="number" step="any"/></label><label>Y 最大值<input v-model.number="s.yMax" type="number" step="any"/></label></div><label class="check-row"><input v-model="s.grid" type="checkbox"/>显示网格与坐标轴</label><p class="small muted">支持 + − * / ^、sin/cos/tan、sqrt、abs、ln、log、exp、pi、e。乘法请显式写为 2*x。</p></section></div><section class="settings-card guide"><div><h2>按住快捷键，顺手一点</h2><p><kbd>Ctrl</kbd> 自由笔迹规整为直线/平滑曲线；直线吸附 45°；矩形、椭圆约束为正方形、正圆。</p><p><kbd>Alt + 点击</kbd> 临时隐藏画板，取下方屏幕的真实颜色，随后自动恢复原工具。</p><p><kbd>Ctrl+Shift+D</kbd> 绘画/鼠标穿透切换。穿透时工具条仍可点击。<kbd>Esc</kbd> 收起画板。</p><p>选择工具可拖动对象、滚轮缩放，双击文字可编辑。橡皮删除整个对象，可撤销。</p></div><aside><strong>画面只在本机</strong><p>不截图上传、不联网、不修改下面的应用。收起后仍保留画面；禁用后隐藏，卸载模块或关闭工具箱后清空画面。</p></aside></section><footer class="settings-footer"><span class="muted">{{saved?'设置已保存':state?.active?'已启用 · 可以打开画板':'请在工具箱模块页启用此模块后打开画板'}}</span><QButton :loading="busy" @click="save">保存设置</QButton><QButton variant="primary" :loading="busy" @click="open">保存并打开画板</QButton></footer></main></template>
